INSERT INTO events (title, category, is_vip, date_text, city, price_m, price_f, summary, intro, notice, image, status, created_at, updated_at) VALUES
('攝影聯誼｜鏡頭下的愛情曝光', 'other', 0, '01/11 (六)', '台北', 1000, 800, '拿起相機，透過鏡頭認識彼此，捕捉最自然的心動瞬間。', '<p>由專業攝影師帶領，教你基本構圖與人像拍攝技巧，一邊學習一邊互動，讓陌生的兩人透過鏡頭快速拉近距離。</p>', '<p>※ 報名成功不代表有參加資格，請以戀愛秘書通知為準。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000),
('夏日創意芬芳｜手作乾燥花香蠟燭', 'craft', 0, '01/18 (六)', '台北', 1500, 1200, '親手做一顆專屬香氛蠟燭，在花香中認識新朋友。', '<p>從選色、擺花到灌蠟，一步步完成獨一無二的乾燥花香蠟燭。過程輕鬆又療癒，最適合手作派對。</p>', '<p>※ 材料費已包含於活動費用中。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000),
('電玩派對聯誼', 'game', 0, '01/25 (六)', '台北', 1200, 1000, 'Switch、桌遊、體感遊戲一次玩個夠，在歡笑中破冰！', '<p>各式熱門派對遊戲任你玩，分組競賽讓氣氛瞬間升溫，不怕沒話聊，只怕玩不夠。</p>', '<p>※ 為顧及活動品質，採事先報名。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000),
('保齡球 PK 大賽', 'game', 0, '02/01 (六)', '台北', 1200, 1000, '揮出全倒的瞬間，也擊出戀愛的火花！', '<p>不論新手老手都能同樂，分組對戰、加油打氣，最自然的互動就在球道旁。</p>', '<p>※ 網站公告之費用為活動保證金。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000),
('手作玫瑰蘋果塔', 'craft', 0, '02/08 (六)', '台北', 1500, 1200, '把蘋果片捲成玫瑰，做出浪漫又美味的甜點。', '<p>甜點老師手把手教學，即使是廚房新手也能做出漂亮的玫瑰蘋果塔，成品可帶回家分享。</p>', '<p>※ 成品可打包帶走。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000),
('改變形象｜型男養成術', 'talk', 1, '預約制', '台北', 1000, 0, 'VIP 限定！專業形象顧問量身打造你的型男風格。', '<p>特別聘請男性私人穿搭顧問，為你量身改造髮型與穿搭，帶你走出宅男生活、邁向型男新世界！採預約制，個案服務，時間約 1.5 小時。</p>', '<p>※ 本活動為 VIP 限定，髮型與治裝費需自付。<br>※ 活動時間請洽戀愛秘書預約。</p>', '', 1, strftime('%s','now')*1000, strftime('%s','now')*1000);
